steps.code:
res_state = primitives.call(name="observe_maniskill_state", include_raw=True)
res_ctrl = primitives.call(name="observe_maniskill_control_state")
res_inst_base = primitives.call(
    name="list_maniskill_instances", camera_uid="base_camera", min_pixel_count=1
)
res_inst_hand = primitives.call(
    name="list_maniskill_instances", camera_uid="hand_camera", min_pixel_count=1
)

print("State ok:", res_state.ok)
if res_state.ok:
    print("State keys:", list(res_state.output.keys()))
    print("goal_xyz:", res_state.output.get("goal_xyz"))
    print("extra:", res_state.output.get("extra"))
    print("agent:", res_state.output.get("agent"))

print("Ctrl ok:", res_ctrl.ok)
if res_ctrl.ok:
    print("Ctrl:", res_ctrl.output)

if res_inst_base.ok:
    print("Base instances:")
    for inst in res_inst_base.output.get("instances", []):
        print(" ", inst)

if res_inst_hand.ok:
    print("Hand instances:")
    for inst in res_inst_hand.output.get("instances", []):
        print(" ", inst)

print("=== Base camera instances ===")
for inst in res_inst_base.output["instances"]["base_camera"]:
    print(
        f"ID {inst['segmentation_id']}: pixels={inst['pixel_count']}, bbox={inst['bbox_xyxy']}, world_med={inst['world_median_m']}, bounds_min={inst['world_bounds_m']['min']}, bounds_max={inst['world_bounds_m']['max']}, rgb_med={inst['rgb_median']}"
    )

print("=== Hand camera instances ===")
for inst in res_inst_hand.output["instances"]["hand_camera"]:
    print(
        f"ID {inst['segmentation_id']}: pixels={inst['pixel_count']}, bbox={inst['bbox_xyxy']}, world_med={inst['world_median_m']}, bounds_min={inst['world_bounds_m']['min']}, bounds_max={inst['world_bounds_m']['max']}, rgb_med={inst['rgb_median']}"
    )

